96	// A pipe cut off with an error is a read failure, unlike a pipe closed
97	// normally after a prefix (which is an honestly truncated snapshot).
98	func TestRestorePipeClosedWithErrorIsReadFailure(t *testing.T) {
99		index := txChain(t, []string{"a"}, []string{"b"})
100		blocks, byHash, tip := snapshot(index)
101		pr, pw := io.Pipe()
102		done := make(chan error, 1)
103		go func() { done <- index.Restore(pr) }()
104		if _, err := pw.Write([]byte(halfSnapshot)); err != nil {
105			t.Fatal(err)
106		}
107		if err := pw.CloseWithError(io.ErrUnexpectedEOF); err != nil {
108			t.Fatal(err)
109		}
110		err := <-done
111		if errors.Is(err, ErrInvalidSnapshot) {
112			t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
113		}
114		if !errors.Is(err, io.ErrUnexpectedEOF) {
115			t.Fatalf("err=%v, want errors.Is ErrUnexpectedEOF", err)
116		}
117		if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
118			t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
119		}
120		requireUnchanged(t, index, blocks, byHash, tip)
121	}
