143	func TestRestoreCompleteDocArrivingWithFaultIsReadFailure(t *testing.T) {
144		index := txChain(t, []string{"a"}, []string{"b"})
145		blocks, byHash, tip := snapshot(index)
146		raw := exportString(t, index)
147		// The single read hands over a whole, valid snapshot together with the
148		// fault and never signals a clean EOF: the stream failed, so Restore must
149		// not apply it.
