182	// A content error found in bytes that arrived together with a read fault is
183	// still a read failure: the stream failed, so the bytes cannot be trusted to
184	// be the whole document. The same bytes read to a clean end stay content
185	// errors.
186	func TestRestoreContentErrorWithFaultIsReadFailure(t *testing.T) {
187		cases := map[string]string{
188			"unknown top-level field":   `{"version":1,"tip":0,"blocks":[],"extra":0}`,
189			"duplicate top-level field": `{"version":1,"version":1,"tip":0,"blocks":[]}`,
190			"top level not an object":   `["version",1]`,
191		}
192		for name, doc := range cases {
193			t.Run(name, func(t *testing.T) {
194				index := txChain(t, []string{"a"}, []string{"b"})
