288		err = index.Restore(&oneShotReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF})
289		if !errors.Is(err, io.ErrUnexpectedEOF) || errors.Is(err, ErrInvalidSnapshot) {
290			t.Fatalf("err=%v, want a read failure distinct from ErrInvalidSnapshot", err)
291		}
