package indexroom

import (
	"errors"
	"fmt"
	"io"
	"reflect"
	"strings"
	"testing"
)

// oneShotReader delivers all of data together with err on the first Read and
// clean io.EOF forever after, modelling a Reader whose single read returns
// valid bytes and a fault at once.
type oneShotReader struct {
	done bool
	data []byte
	err  error
}

func (r *oneShotReader) Read(p []byte) (int, error) {
	if r.done {
		return 0, io.EOF
	}
	r.done = true
	if len(r.data) == 0 {
		return 0, r.err
	}
	n := copy(p, r.data)
	return n, r.err
}

// halfSnapshot is a syntactically valid prefix that cannot be a complete
// snapshot; the same bytes end normally in one case and with a fault in the
// other.
const halfSnapshot = `{"version":1,"tip":2,"blocks":[` +
	`{"height":1,"hash":"h1","parent":"g","txs":[]},` +
	`{"height":2,"hash":"h2","parent":"h1","txs":`

// errStorageOffline is a non-EOF read fault unrelated to JSON shape.
var errStorageOffline = errors.New("storage offline")

func TestRestoreUnexpectedEOFIsReadFailure(t *testing.T) {
	cases := map[string]struct {
		r       io.Reader
		wantErr error
	}{
		"bare ErrUnexpectedEOF after prefix": {
			&errReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF},
			io.ErrUnexpectedEOF,
		},
		"wrapped ErrUnexpectedEOF after prefix": {
			&errReader{data: []byte(halfSnapshot), err: fmt.Errorf("storage cut: %w", io.ErrUnexpectedEOF)},
			io.ErrUnexpectedEOF,
		},
		"bytes and bare ErrUnexpectedEOF in one read": {
			&oneShotReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF},
			io.ErrUnexpectedEOF,
		},
		"bytes and wrapped ErrUnexpectedEOF in one read": {
			&oneShotReader{data: []byte(halfSnapshot), err: fmt.Errorf("storage cut: %w", io.ErrUnexpectedEOF)},
			io.ErrUnexpectedEOF,
		},
		"fault in one read at a complete token boundary": {
			&oneShotReader{data: []byte(`{"version":1,`), err: io.ErrUnexpectedEOF},
			io.ErrUnexpectedEOF,
		},
		"empty read returning ErrUnexpectedEOF": {
			&oneShotReader{err: io.ErrUnexpectedEOF},
			io.ErrUnexpectedEOF,
		},
		"bytes and a generic fault in one read": {
			&oneShotReader{data: []byte(halfSnapshot), err: errStorageOffline},
			errStorageOffline,
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			index := txChain(t, []string{"a"}, []string{"b"})
			blocks, byHash, tip := snapshot(index)
			err := index.Restore(tc.r)
			if errors.Is(err, ErrInvalidSnapshot) {
				t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
			}
			if !errors.Is(err, tc.wantErr) {
				t.Fatalf("err=%v, want errors.Is %v", err, tc.wantErr)
			}
			if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
				t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
			}
			requireUnchanged(t, index, blocks, byHash, tip)
		})
	}
}

// A pipe cut off with an error is a read failure, unlike a pipe closed
// normally after a prefix (which is an honestly truncated snapshot).
func TestRestorePipeClosedWithErrorIsReadFailure(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"})
	blocks, byHash, tip := snapshot(index)
	pr, pw := io.Pipe()
	done := make(chan error, 1)
	go func() { done <- index.Restore(pr) }()
	if _, err := pw.Write([]byte(halfSnapshot)); err != nil {
		t.Fatal(err)
	}
	if err := pw.CloseWithError(io.ErrUnexpectedEOF); err != nil {
		t.Fatal(err)
	}
	err := <-done
	if errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
	}
	if !errors.Is(err, io.ErrUnexpectedEOF) {
		t.Fatalf("err=%v, want errors.Is ErrUnexpectedEOF", err)
	}
	if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
		t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
	}
	requireUnchanged(t, index, blocks, byHash, tip)
}

func TestRestoreSameHalfBytesCleanEOFVsFault(t *testing.T) {
	// Normal end after the same half document: truncated content, not a read
	// failure.
	index := txChain(t, []string{"a"}, []string{"b"})
	err := index.Restore(strings.NewReader(halfSnapshot))
	if !errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("clean EOF: err=%v, want ErrInvalidSnapshot", err)
	}

	// Read failure on the same bytes: a different error category.
	index = txChain(t, []string{"a"}, []string{"b"})
	err = index.Restore(&oneShotReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF})
	if errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("fault: err=%v, must not be ErrInvalidSnapshot", err)
	}
	if !errors.Is(err, io.ErrUnexpectedEOF) {
		t.Fatalf("fault: err=%v, want errors.Is ErrUnexpectedEOF", err)
	}
}

func TestRestoreCompleteDocArrivingWithFaultIsReadFailure(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"})
	blocks, byHash, tip := snapshot(index)
	raw := exportString(t, index)
	// The single read hands over a whole, valid snapshot together with the
	// fault and never signals a clean EOF: the stream failed, so Restore must
	// not apply it.
	err := index.Restore(&oneShotReader{data: []byte(raw), err: io.ErrUnexpectedEOF})
	if errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
	}
	if !errors.Is(err, io.ErrUnexpectedEOF) {
		t.Fatalf("err=%v, want errors.Is ErrUnexpectedEOF", err)
	}
	requireUnchanged(t, index, blocks, byHash, tip)
}

// scriptReader delivers each chunk in order, one Read per chunk, pairing the
// chunk's bytes with its error exactly as an underlying stream might; once
// the chunks run out it ends normally.
type scriptReader struct {
	chunks []scriptChunk
}

type scriptChunk struct {
	data string
	err  error
}

func (r *scriptReader) Read(p []byte) (int, error) {
	if len(r.chunks) == 0 {
		return 0, io.EOF
	}
	chunk := r.chunks[0]
	r.chunks = r.chunks[1:]
	n := copy(p, chunk.data)
	return n, chunk.err
}

// A content error found in bytes that arrived together with a read fault is
// still a read failure: the stream failed, so the bytes cannot be trusted to
// be the whole document. The same bytes read to a clean end stay content
// errors.
func TestRestoreContentErrorWithFaultIsReadFailure(t *testing.T) {
	cases := map[string]string{
		"unknown top-level field":   `{"version":1,"tip":0,"blocks":[],"extra":0}`,
		"duplicate top-level field": `{"version":1,"version":1,"tip":0,"blocks":[]}`,
		"top level not an object":   `["version",1]`,
	}
	for name, doc := range cases {
		t.Run(name, func(t *testing.T) {
			index := txChain(t, []string{"a"}, []string{"b"})
			blocks, byHash, tip := snapshot(index)
			err := index.Restore(&oneShotReader{data: []byte(doc), err: errStorageOffline})
			if errors.Is(err, ErrInvalidSnapshot) {
				t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
			}
			if !errors.Is(err, errStorageOffline) {
				t.Fatalf("err=%v, want errors.Is errStorageOffline", err)
			}
			if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
				t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
			}
			requireUnchanged(t, index, blocks, byHash, tip)

			// The same bytes delivered to a clean end report the content
			// error instead.
			index = txChain(t, []string{"a"}, []string{"b"})
			err = index.Restore(strings.NewReader(doc))
			if !errors.Is(err, ErrInvalidSnapshot) {
				t.Fatalf("clean EOF: err=%v, want ErrInvalidSnapshot", err)
			}
		})
	}
}

// Trailing data after the object is a read failure when the read that fetched
// those bytes already reported the fault, whether the fault arrived with the
// object's final bytes or only with the trailing ones.
func TestRestoreTrailingDataWithFaultIsReadFailure(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"})
	raw := exportString(t, index)
	cases := map[string]io.Reader{
		"fault with the trailing bytes": &scriptReader{chunks: []scriptChunk{
			{data: raw},
			{data: " 2", err: io.ErrUnexpectedEOF},
		}},
		"fault with the whole stream": &oneShotReader{
			data: []byte(raw + " 2"),
			err:  errStorageOffline,
		},
	}
	for name, r := range cases {
		t.Run(name, func(t *testing.T) {
			index := txChain(t, []string{"a"}, []string{"b"})
			blocks, byHash, tip := snapshot(index)
			err := index.Restore(r)
			if errors.Is(err, ErrInvalidSnapshot) {
				t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
			}
			if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
				t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
			}
			requireUnchanged(t, index, blocks, byHash, tip)
		})
	}

	// The same trailing bytes read to a clean end stay a content error.
	index = txChain(t, []string{"a"}, []string{"b"})
	if err := index.Restore(strings.NewReader(raw + " 2")); !errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("clean EOF: err=%v, want ErrInvalidSnapshot", err)
	}
}

// Only a fault already received wins. A content error found before the reader
// has reported any failure rejects the snapshot as invalid right away, without
// reading ahead to look for a fault.
func TestRestoreContentErrorBeforeFaultStaysInvalid(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"})
	blocks, byHash, tip := snapshot(index)
	err := index.Restore(&scriptReader{chunks: []scriptChunk{
		{data: `{"version":1,"extra":0,"tip":0,"blocks":[]}`},
		{err: errStorageOffline},
	}})
	if !errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("err=%v, want ErrInvalidSnapshot", err)
	}
	if errors.Is(err, errStorageOffline) {
		t.Fatalf("err=%v, must not read ahead into the fault", err)
	}
	requireUnchanged(t, index, blocks, byHash, tip)
}

func TestRestoreReadFailureKeepsChainAndCursor(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"}, []string{"c"})
	first, err := index.QueryTxs(TxQuery{PageSize: 1})
	if err != nil {
		t.Fatal(err)
	}
	cursor := first.NextCursor
	if cursor == "" {
		t.Fatal("expected a continuation cursor")
	}
	blocks, byHash, tip := snapshot(index)

	err = index.Restore(&oneShotReader{data: []byte(halfSnapshot), err: io.ErrUnexpectedEOF})
	if !errors.Is(err, io.ErrUnexpectedEOF) || errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("err=%v, want a read failure distinct from ErrInvalidSnapshot", err)
	}
	requireUnchanged(t, index, blocks, byHash, tip)

	// The pre-failure cursor keeps paging the original chain; the failed read
	// must not be reported as ErrQueryChanged.
	pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: cursor})
	var all []TxHit
	for _, page := range pages {
		all = append(all, page.Hits...)
	}
	want := []TxHit{
		{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
		{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
	}
	if !reflect.DeepEqual(all, want) {
		t.Fatalf("hits after read failure=%v, want %v", all, want)
	}
}

// eofWrapErr is an io.EOF carrying storage-side context: errors.Is matches
// io.EOF, but it is not the bare sentinel the decoder takes for a normal end
// of input.
type eofWrapErr struct{ err error }

func (e *eofWrapErr) Error() string { return "storage at EOF: " + e.err.Error() }
func (e *eofWrapErr) Unwrap() error { return e.err }

// oneBlockV1 is a complete, valid one-block version-1 snapshot; restored over
// a multi-block index it would visibly shorten the chain if it were applied.
const oneBlockV1 = `{"version":1,"tip":1,"blocks":[` +
	`{"height":1,"hash":"g1","parent":"g","txs":[]}]}`

// oneBlockV2 is the same snapshot in the version-2 layout.
const oneBlockV2 = `{"version":2,"tip":1,"blocks":[` +
	`{"height":1,"hash":"g1","parent":"g","txs":[],"timestamp":null}]}`

// Only the bare io.EOF the reader returns directly marks the normal end of a
// restore stream. An io.EOF carrying context, and a combined error joining
// io.EOF with a storage fault (as errors.Join produces), are read failures
// whether they arrive alone or together with usable bytes, and whether those
// bytes already form a complete JSON object or only a prefix.
func TestRestoreJoinedOrWrappedEOFIsReadFailure(t *testing.T) {
	joined := errors.Join(io.EOF, errStorageOffline)
	wrapped := &eofWrapErr{err: io.EOF}
	cases := map[string]struct {
		r         io.Reader
		wantFault bool
	}{
		"joined EOF and fault with a complete snapshot": {
			&oneShotReader{data: []byte(oneBlockV1), err: joined}, true,
		},
		"joined EOF and fault with a half snapshot": {
			&oneShotReader{data: []byte(halfSnapshot), err: joined}, true,
		},
		"joined EOF and fault without bytes": {
			&oneShotReader{err: joined}, true,
		},
		"wrapped EOF with a complete snapshot": {
			&oneShotReader{data: []byte(oneBlockV1), err: wrapped}, false,
		},
		"wrapped EOF with a half snapshot": {
			&oneShotReader{data: []byte(halfSnapshot), err: wrapped}, false,
		},
		"wrapped EOF without bytes": {
			&oneShotReader{err: wrapped}, false,
		},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			index := txChain(t, []string{"a"}, []string{"b"})
			blocks, byHash, tip := snapshot(index)
			err := index.Restore(tc.r)
			if err == nil {
				t.Fatal("expected a read failure, got success")
			}
			if errors.Is(err, ErrInvalidSnapshot) {
				t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
			}
			if !errors.Is(err, io.EOF) {
				t.Fatalf("err=%v, caller must still errors.Is the end marker", err)
			}
			if tc.wantFault && !errors.Is(err, errStorageOffline) {
				t.Fatalf("err=%v, caller must errors.Is the storage fault", err)
			}
			if !strings.HasPrefix(err.Error(), "indexroom: read snapshot:") {
				t.Fatalf("err=%q, want the read-snapshot prefix", err.Error())
			}
			requireUnchanged(t, index, blocks, byHash, tip)
		})
	}
}

// The scenario from the fault report: a three-block chain fed a valid
// one-block snapshot whose final bytes arrive together with a combined
// io.EOF+storage error must fail as a read failure with the whole chain
// intact — never shorten the chain first and then error — and a cursor taken
// before the attempt keeps paging the original transactions.
func TestRestoreJoinedEOFReadFailureKeepsChainAndCursor(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"}, []string{"c"})
	first, err := index.QueryTxs(TxQuery{PageSize: 1})
	if err != nil {
		t.Fatal(err)
	}
	cursor := first.NextCursor
	if cursor == "" {
		t.Fatal("expected a continuation cursor")
	}
	blocks, byHash, tip := snapshot(index)

	err = index.Restore(&oneShotReader{
		data: []byte(oneBlockV1),
		err:  errors.Join(io.EOF, errStorageOffline),
	})
	if err == nil {
		t.Fatal("expected a read failure, got success")
	}
	if errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
	}
	if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
		t.Fatalf("err=%v, want errors.Is both io.EOF and the storage fault", err)
	}
	requireUnchanged(t, index, blocks, byHash, tip)

	pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: cursor})
	var all []TxHit
	for _, page := range pages {
		all = append(all, page.Hits...)
	}
	want := []TxHit{
		{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
		{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
	}
	if !reflect.DeepEqual(all, want) {
		t.Fatalf("hits after read failure=%v, want %v", all, want)
	}
}

// A fault already received is sticky: even if the underlying stream then
// "recovers", delivers the bytes that complete the document, and ends with a
// clean io.EOF, the failure cannot be erased and the snapshot is not applied.
func TestRestoreFaultNotErasedByLaterCleanEOF(t *testing.T) {
	index := txChain(t, []string{"a"}, []string{"b"})
	blocks, byHash, tip := snapshot(index)
	r := &scriptReader{chunks: []scriptChunk{
		// The prefix arrives together with the combined fault.
		{data: halfSnapshot, err: errors.Join(io.EOF, errStorageOffline)},
		// The reader then oddly resumes with the rest of the document...
		{data: `[]]}`},
		// ...and finally signals a clean end.
	}}
	err := index.Restore(r)
	if errors.Is(err, ErrInvalidSnapshot) {
		t.Fatalf("err=%v, must not be ErrInvalidSnapshot", err)
	}
	if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
		t.Fatalf("err=%v, want the first fault preserved, not erased by the clean EOF", err)
	}
	requireUnchanged(t, index, blocks, byHash, tip)
}

// Fault/content precedence with combined EOF errors: a content error exposed
// by the same batch of bytes that already carries a read fault yields the read
// failure; a content error found while the reader has not yet reported any
// fault rejects the snapshot as invalid immediately, without consuming the
// joined EOF+fault that comes next.
func TestRestoreJoinedEOFPrecedenceAndEarlyReject(t *testing.T) {
	contentBad := `{"version":1,"tip":0,"blocks":[],"extra":0}`

	t.Run("fault already reported outranks content error", func(t *testing.T) {
		index := txChain(t, []string{"a"}, []string{"b"})
		blocks, byHash, tip := snapshot(index)
		err := index.Restore(&oneShotReader{
			data: []byte(contentBad),
			err:  errors.Join(io.EOF, errStorageOffline),
		})
		if errors.Is(err, ErrInvalidSnapshot) {
			t.Fatalf("err=%v, must not match ErrInvalidSnapshot", err)
		}
		if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
			t.Fatalf("err=%v, want errors.Is io.EOF and the storage fault", err)
		}
		requireUnchanged(t, index, blocks, byHash, tip)
	})

	t.Run("content error first rejects without reading ahead", func(t *testing.T) {
		index := txChain(t, []string{"a"}, []string{"b"})
		blocks, byHash, tip := snapshot(index)
		err := index.Restore(&scriptReader{chunks: []scriptChunk{
			{data: contentBad},
			{err: errors.Join(io.EOF, errStorageOffline)},
		}})
		if !errors.Is(err, ErrInvalidSnapshot) {
			t.Fatalf("err=%v, want ErrInvalidSnapshot", err)
		}
		if errors.Is(err, errStorageOffline) || errors.Is(err, io.EOF) {
			t.Fatalf("err=%v, must not consume the stream looking for a fault", err)
		}
		requireUnchanged(t, index, blocks, byHash, tip)
	})
}

// Both supported snapshot versions keep the same EOF rule: a combined
// io.EOF+fault ending is a read failure, while the same documents ending with
// a bare, direct io.EOF still restore successfully.
func TestRestoreJoinedEOFReadFailureBothVersions(t *testing.T) {
	for name, doc := range map[string]string{"version 1": oneBlockV1, "version 2": oneBlockV2} {
		t.Run(name, func(t *testing.T) {
			index := txChain(t, []string{"a"}, []string{"b"})
			blocks, byHash, tip := snapshot(index)
			err := index.Restore(&oneShotReader{
				data: []byte(doc),
				err:  errors.Join(io.EOF, errStorageOffline),
			})
			if errors.Is(err, ErrInvalidSnapshot) {
				t.Fatalf("fault: err=%v, must not be ErrInvalidSnapshot", err)
			}
			if !errors.Is(err, io.EOF) || !errors.Is(err, errStorageOffline) {
				t.Fatalf("fault: err=%v, want errors.Is io.EOF and the storage fault", err)
			}
			requireUnchanged(t, index, blocks, byHash, tip)

			// The identical document ending with a bare io.EOF still applies.
			if err := index.Restore(strings.NewReader(doc)); err != nil {
				t.Fatalf("clean EOF restore failed: %v", err)
			}
			if index.Tip != 1 || index.ByHash["g1"] != 1 {
				t.Fatalf("clean restore did not apply the one-block chain: tip=%d byHash=%v", index.Tip, index.ByHash)
			}
		})
	}
}

// 快照恢复（Index.Export / Index.Restore）完整示例：用导出的较短新链快照
// 整体替换较长旧链，展示替换前后的链顶、交易查询与再次导出；再展示最后一个
// 区块父哈希错误的快照被整体拒绝（ErrInvalidSnapshot）、链与游标保持原状，
// 以及读取输入失败与非法快照的区分、恢复成功后旧游标返回 ErrQueryChanged。
//
// 运行：go run ./examples/restore
package main

import (
	"bytes"
	"errors"
	"fmt"
	"strings"

	"github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

func mustAppend(index *indexroom.Index, block indexroom.Block) {
	if err := index.Append(block); err != nil {
		panic(err)
	}
}

// unix 返回指向给定 Unix 秒的指针，用于设置区块时间。
func unix(sec int64) *int64 { return &sec }

// querySet 同时包含旧链独有标识、新链独有标识与两链共有的标识，
// 让一次查询就能看出哪些交易被替换。
var querySet = []string{"alpha", "OLD-4", "beta"}

func exportString(index *indexroom.Index) string {
	var buf bytes.Buffer
	if err := index.Export(&buf); err != nil {
		panic(err)
	}
	return buf.String()
}

// dumpState 打印当前链顶、固定筛选下的交易查询首页和再次导出内容，
// 每次调用都看到一个完整的链状态。
func dumpState(index *indexroom.Index) {
	fmt.Printf("  链顶 tip=%d\n", index.Tip)
	page, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 4, TxIDs: querySet})
	if err != nil {
		panic(err)
	}
	fmt.Printf("  查询高度 [1, 4] 内标识 %v（空游标首页，ToHeight=%d）：TotalMatches=%d MatchedBlocks=%d\n",
		querySet, page.ToHeight, page.TotalMatches, page.MatchedBlocks)
	for _, hit := range page.Hits {
		fmt.Printf("    命中 height=%d block=%s tx=%q position=%d\n",
			hit.Height, hit.BlockHash, hit.TxID, hit.Position)
	}
	fmt.Printf("  再次导出：%s\n", exportString(index))
}

// failAfterReader 先送出 data，随后始终返回 err，模拟读取快照途中存储故障。
type failAfterReader struct {
	data []byte
	err  error
}

func (r *failAfterReader) Read(p []byte) (int, error) {
	if len(r.data) == 0 {
		return 0, r.err
	}
	n := copy(p, r.data)
	r.data = r.data[n:]
	return n, nil
}

func main() {
	// 1. 预先准备一条较长的旧链（4 个区块，全部没有时间，导出为版本 1）。
	target := indexroom.New()
	mustAppend(target, indexroom.Block{Height: 1, Hash: "s1", Parent: "genesis", Txs: []string{"alpha", "OLD-1"}})
	mustAppend(target, indexroom.Block{Height: 2, Hash: "s2", Parent: "s1", Txs: []string{"alpha"}})
	mustAppend(target, indexroom.Block{Height: 3, Hash: "s3", Parent: "s2", Txs: []string{"OLD-3"}})
	mustAppend(target, indexroom.Block{Height: 4, Hash: "s4", Parent: "s3", Txs: []string{"OLD-4", "alpha"}})
	fmt.Println("操作 1：准备较长旧链（4 个区块）后的状态")
	oldExport := exportString(target)
	dumpState(target)
	fmt.Println()

	// 2. 用现有导出功能从另一条较短的新链取得快照（2 个区块）。
	//    高度 1 时间为 0（真实时间戳），高度 2 没有时间；只要有一个区块带时间，
	//    导出即为版本 2，每块都带 timestamp：0 与 null 同时出现。
	source := indexroom.New()
	mustAppend(source, indexroom.Block{Height: 1, Hash: "n1", Parent: "genesis", Txs: []string{"alpha"}, Time: unix(0)})
	mustAppend(source, indexroom.Block{Height: 2, Hash: "n2", Parent: "n1", Txs: []string{"beta"}})
	snapshot := exportString(source)
	fmt.Printf("操作 2：从较短新链（2 个区块）Export 出快照\n  %s\n\n", snapshot)

	// 3. 在旧链上取得两个分页游标（同一固定范围 [1, 4]、同一筛选，每页 2 条），
	//    分别留给“恢复被拒绝”和“恢复成功”之后续查。
	query := indexroom.TxQuery{From: 1, To: 4, TxIDs: querySet, PageSize: 2}
	firstA, err := target.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	firstB, err := target.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	cursorAfterReject := firstA.NextCursor
	cursorAfterRestore := firstB.NextCursor
	fmt.Printf("操作 3：旧链固定范围 [1, 4] 首页（每页 2 条）命中：")
	for _, hit := range firstA.Hits {
		fmt.Printf("%d/%s ", hit.Height, hit.TxID)
	}
	fmt.Printf("剩余记录由游标续查（游标不透明，不展示内容）\n\n")

	// 4a. 拒绝情形之一：把两份快照文档拼在一起不是合法输入，
	//     只允许一份完整 JSON 文档（结尾可以有空白）。
	err = target.Restore(strings.NewReader(snapshot + snapshot))
	fmt.Printf("操作 4a：拼接两份文档后 Restore：err=%v\n", err)
	fmt.Printf("  errors.Is(err, ErrInvalidSnapshot)=%v，链顶仍为 tip=%d\n\n",
		errors.Is(err, indexroom.ErrInvalidSnapshot), target.Tip)

	// 4b. 拒绝情形之二：最后一个区块的父哈希被改错。前一个区块完全合法，
	//     但整份快照必须在应用前全部校验通过，因此不会有任何部分导入。
	broken := strings.Replace(snapshot, `"parent":"n1"`, `"parent":"WRONG-PARENT"`, 1)
	err = target.Restore(strings.NewReader(broken))
	fmt.Printf("操作 4b：最后一个区块父哈希错误后 Restore：err=%v\n", err)
	fmt.Printf("  errors.Is(err, ErrInvalidSnapshot)=%v（具体原因已在错误信息中指出）\n",
		errors.Is(err, indexroom.ErrInvalidSnapshot))
	fmt.Println("拒绝后的状态（应与操作 1 完全一致，不能出现新链区块）：")
	dumpState(target)
	fmt.Printf("  导出内容与恢复前逐字节一致：%v\n", exportString(target) == oldExport)
	// 恢复失败前取得的游标仍可用于原链，继续读出旧链高度 4 的两条记录。
	cont, err := target.QueryTxs(indexroom.TxQuery{
		From: 1, To: 4, TxIDs: querySet, PageSize: 2, Cursor: cursorAfterReject,
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("  旧游标续查成功（err=%v），本页命中：", err)
	for _, hit := range cont.Hits {
		fmt.Printf("%d/%s ", hit.Height, hit.TxID)
	}
	fmt.Println()
	fmt.Println()

	// 4c. 区分读取输入发生的错误：读到一半底层 reader 故障。
	//     原始读取错误仍可用 errors.Is 识别，它不是 ErrInvalidSnapshot；
	//     这种情况同样不改变现有链。
	readProblem := errors.New("simulated storage read failure")
	err = target.Restore(&failAfterReader{data: []byte(snapshot[:len(snapshot)/2]), err: readProblem})
	fmt.Printf("操作 4c：读取途中故障后 Restore：err=%v\n", err)
	fmt.Printf("  errors.Is(err, 读取错误)=%v errors.Is(err, ErrInvalidSnapshot)=%v 链顶仍为 tip=%d\n\n",
		errors.Is(err, readProblem), errors.Is(err, indexroom.ErrInvalidSnapshot), target.Tip)

	// 5. 成功恢复：输入是一份完整 JSON 快照，结尾允许空白（这里追加一个换行）。
	//    Restore 用快照整体替换主链，不与旧链合并。
	err = target.Restore(strings.NewReader(snapshot + "\n"))
	fmt.Printf("操作 5：用合法短链快照（结尾带换行）Restore：err=%v\n", err)
	fmt.Println("成功恢复后的状态（旧链多出的高度 3、4 与被替换的交易应全部消失）：")
	dumpState(target)
	fmt.Printf("  再次导出与操作 2 的快照逐字节一致：%v\n", exportString(target) == snapshot)
	// 旧游标遵循既有固定范围规则：固定上界为 4，链顶已降到 2，续查返回
	// ErrQueryChanged 而不是部分数据；应从空游标重新开始查询。
	_, err = target.QueryTxs(indexroom.TxQuery{
		From: 1, To: 4, TxIDs: querySet, PageSize: 2, Cursor: cursorAfterRestore,
	})
	fmt.Printf("  旧游标续查：errors.Is(err, ErrQueryChanged)=%v errors.Is(err, ErrInvalidArgument)=%v\n",
		errors.Is(err, indexroom.ErrQueryChanged), errors.Is(err, indexroom.ErrInvalidArgument))
	restart, err := target.QueryTxs(indexroom.TxQuery{From: 1, To: 4, TxIDs: querySet, PageSize: 2})
	if err != nil {
		panic(err)
	}
	fmt.Printf("  从空游标重新开始：ToHeight=%d 命中：", restart.ToHeight)
	for _, hit := range restart.Hits {
		fmt.Printf("%d/%s ", hit.Height, hit.TxID)
	}
	fmt.Printf("有后续游标=%v\n", restart.NextCursor != "")
}

### 恢复与分页游标

- **恢复失败**（快照被拒或读取出错）：链没有变化，失败前取得的游标仍可用于原链，按[分页查询的既有规则](#游标失效区分-errquerychanged-与-errinvalidargument)继续翻页。
- **恢复成功**：旧游标不是整体作废，而是遵循同一套固定范围规则继续校验——固定范围内的区块内容变了（即使只是时间变化），或链顶降到该查询固定上界以下，续查返回 `ErrQueryChanged` 且没有可用页结果；此时应**从空游标重新开始查询**，不要把新页拼到旧结果后面。若恢复后的链在固定范围内与首页完全相同且链顶仍覆盖该范围，游标仍可正常续查。

### 完整示例：整体替换、非法拒绝与游标

下面的程序只使用现有公开功能，在本机离线即可运行，源码位于 [`examples/restore/main.go`](examples/restore/main.go)：

```bash
go run ./examples/restore
```

场景：先准备一条 4 个区块的较长旧链（全部无时间，导出为版本 1）；再用 `Export` 从另一条 2 个区块的较短新链取得版本 2 快照——高度 1 时间为 0、高度 2 缺失时间（`timestamp` 分别为 `0` 和 `null`）。程序先展示拼接两份文档与**最后一个区块父哈希错误**两种输入被 `ErrInvalidSnapshot` 拒绝、链与游标保持原状（并演示读取途中故障保留原始读取错误）；再用合法快照恢复，输出恢复前后的链顶、交易查询与再次导出内容，可以直接看到旧链多出的高度 3、4 和被替换的交易已经消失，最后演示成功恢复后旧游标返回 `ErrQueryChanged`。本示例的快照由本功能自己 `Export` 产生且恢复后未再修改，所以其中"再次导出与输入逐字节一致"成立——它是上面[充分条件](#数据一致不等于文本一致)的具体演示，不是对任意合法输入的保证。

```go
// 快照恢复（Index.Export / Index.Restore）完整示例：用导出的较短新链快照
// 整体替换较长旧链，展示替换前后的链顶、交易查询与再次导出；再展示最后一个
// 区块父哈希错误的快照被整体拒绝（ErrInvalidSnapshot）、链与游标保持原状，
// 以及读取输入失败与非法快照的区分、恢复成功后旧游标返回 ErrQueryChanged。
//
// 运行：go run ./examples/restore
package main

import (
	"bytes"
	"errors"
	"fmt"
	"strings"

	"github.com/gzhysuiioo/indexroom-analytics/indexroom"
)

func mustAppend(index *indexroom.Index, block indexroom.Block) {
	if err := index.Append(block); err != nil {
		panic(err)
	}
}

// unix 返回指向给定 Unix 秒的指针，用于设置区块时间。
func unix(sec int64) *int64 { return &sec }

// querySet 同时包含旧链独有标识、新链独有标识与两链共有的标识，
// 让一次查询就能看出哪些交易被替换。
var querySet = []string{"alpha", "OLD-4", "beta"}

func exportString(index *indexroom.Index) string {
	var buf bytes.Buffer
	if err := index.Export(&buf); err != nil {
		panic(err)
	}
	return buf.String()
}

// dumpState 打印当前链顶、固定筛选下的交易查询首页和再次导出内容，
// 每次调用都看到一个完整的链状态。
func dumpState(index *indexroom.Index) {
	fmt.Printf("  链顶 tip=%d\n", index.Tip)
	page, err := index.QueryTxs(indexroom.TxQuery{From: 1, To: 4, TxIDs: querySet})
	if err != nil {
		panic(err)
	}
	fmt.Printf("  查询高度 [1, 4] 内标识 %v（空游标首页，ToHeight=%d）：TotalMatches=%d MatchedBlocks=%d\n",
		querySet, page.ToHeight, page.TotalMatches, page.MatchedBlocks)
	for _, hit := range page.Hits {
		fmt.Printf("    命中 height=%d block=%s tx=%q position=%d\n",
			hit.Height, hit.BlockHash, hit.TxID, hit.Position)
	}
	fmt.Printf("  再次导出：%s\n", exportString(index))
}

// failAfterReader 先送出 data，随后始终返回 err，模拟读取快照途中存储故障。
type failAfterReader struct {
	data []byte
	err  error
}

func (r *failAfterReader) Read(p []byte) (int, error) {
	if len(r.data) == 0 {
		return 0, r.err
	}
	n := copy(p, r.data)
	r.data = r.data[n:]
	return n, nil
}

func main() {
	// 1. 预先准备一条较长的旧链（4 个区块，全部没有时间，导出为版本 1）。
	target := indexroom.New()
	mustAppend(target, indexroom.Block{Height: 1, Hash: "s1", Parent: "genesis", Txs: []string{"alpha", "OLD-1"}})
	mustAppend(target, indexroom.Block{Height: 2, Hash: "s2", Parent: "s1", Txs: []string{"alpha"}})
	mustAppend(target, indexroom.Block{Height: 3, Hash: "s3", Parent: "s2", Txs: []string{"OLD-3"}})
	mustAppend(target, indexroom.Block{Height: 4, Hash: "s4", Parent: "s3", Txs: []string{"OLD-4", "alpha"}})
	fmt.Println("操作 1：准备较长旧链（4 个区块）后的状态")
	oldExport := exportString(target)
	dumpState(target)
	fmt.Println()

	// 2. 用现有导出功能从另一条较短的新链取得快照（2 个区块）。
	//    高度 1 时间为 0（真实时间戳），高度 2 没有时间；只要有一个区块带时间，
	//    导出即为版本 2，每块都带 timestamp：0 与 null 同时出现。
	source := indexroom.New()
	mustAppend(source, indexroom.Block{Height: 1, Hash: "n1", Parent: "genesis", Txs: []string{"alpha"}, Time: unix(0)})
	mustAppend(source, indexroom.Block{Height: 2, Hash: "n2", Parent: "n1", Txs: []string{"beta"}})
	snapshot := exportString(source)
	fmt.Printf("操作 2：从较短新链（2 个区块）Export 出快照\n  %s\n\n", snapshot)

	// 3. 在旧链上取得两个分页游标（同一固定范围 [1, 4]、同一筛选，每页 2 条），
	//    分别留给“恢复被拒绝”和“恢复成功”之后续查。
	query := indexroom.TxQuery{From: 1, To: 4, TxIDs: querySet, PageSize: 2}
	firstA, err := target.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	firstB, err := target.QueryTxs(query)
	if err != nil {
		panic(err)
	}
	cursorAfterReject := firstA.NextCursor
	cursorAfterRestore := firstB.NextCursor
	fmt.Printf("操作 3：旧链固定范围 [1, 4] 首页（每页 2 条）命中：")
	for _, hit := range firstA.Hits {
		fmt.Printf("%d/%s ", hit.Height, hit.TxID)
	}
	fmt.Printf("剩余记录由游标续查（游标不透明，不展示内容）\n\n")

	// 4a. 拒绝情形之一：把两份快照文档拼在一起不是合法输入，
	//     只允许一份完整 JSON 文档（结尾可以有空白）。
	err = target.Restore(strings.NewReader(snapshot + snapshot))
	fmt.Printf("操作 4a：拼接两份文档后 Restore：err=%v\n", err)
	fmt.Printf("  errors.Is(err, ErrInvalidSnapshot)=%v，链顶仍为 tip=%d\n\n",
		errors.Is(err, indexroom.ErrInvalidSnapshot), target.Tip)

	// 4b. 拒绝情形之二：最后一个区块的父哈希被改错。前一个区块完全合法，
	//     但整份快照必须在应用前全部校验通过，因此不会有任何部分导入。
	broken := strings.Replace(snapshot, `"parent":"n1"`, `"parent":"WRONG-PARENT"`, 1)
	err = target.Restore(strings.NewReader(broken))
	fmt.Printf("操作 4b：最后一个区块父哈希错误后 Restore：err=%v\n", err)
	fmt.Printf("  errors.Is(err, ErrInvalidSnapshot)=%v（具体原因已在错误信息中指出）\n",
		errors.Is(err, indexroom.ErrInvalidSnapshot))
	fmt.Println("拒绝后的状态（应与操作 1 完全一致，不能出现新链区块）：")
	dumpState(target)
	fmt.Printf("  导出内容与恢复前逐字节一致：%v\n", exportString(target) == oldExport)
	// 恢复失败前取得的游标仍可用于原链，继续读出旧链高度 4 的两条记录。
	cont, err := target.QueryTxs(indexroom.TxQuery{
		From: 1, To: 4, TxIDs: querySet, PageSize: 2, Cursor: cursorAfterReject,
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("  旧游标续查成功（err=%v），本页命中：", err)
	for _, hit := range cont.Hits {
		fmt.Printf("%d/%s ", hit.Height, hit.TxID)
	}
	fmt.Println()
	fmt.Println()

	// 4c. 区分读取输入发生的错误：读到一半底层 reader 故障。
	//     原始读取错误仍可用 errors.Is 识别，它不是 ErrInvalidSnapshot；
	//     这种情况同样不改变现有链。
	readProblem := errors.New("simulated storage read failure")
	err = target.Restore(&failAfterReader{data: []byte(snapshot[:len(snapshot)/2]), err: readProblem})
	fmt.Printf("操作 4c：读取途中故障后 Restore：err=%v\n", err)
	fmt.Printf("  errors.Is(err, 读取错误)=%v errors.Is(err, ErrInvalidSnapshot)=%v 链顶仍为 tip=%d\n\n",
		errors.Is(err, readProblem), errors.Is(err, indexroom.ErrInvalidSnapshot), target.Tip)

	// 5. 成功恢复：输入是一份完整 JSON 快照，结尾允许空白（这里追加一个换行）。
	//    Restore 用快照整体替换主链，不与旧链合并。
	err = target.Restore(strings.NewReader(snapshot + "\n"))
	fmt.Printf("操作 5：用合法短链快照（结尾带换行）Restore：err=%v\n", err)
	fmt.Println("成功恢复后的状态（旧链多出的高度 3、4 与被替换的交易应全部消失）：")
	dumpState(target)
	fmt.Printf("  再次导出与操作 2 的快照逐字节一致：%v\n", exportString(target) == snapshot)
	// 旧游标遵循既有固定范围规则：固定上界为 4，链顶已降到 2，续查返回
	// ErrQueryChanged 而不是部分数据；应从空游标重新开始查询。
	_, err = target.QueryTxs(indexroom.TxQuery{
		From: 1, To: 4, TxIDs: querySet, PageSize: 2, Cursor: cursorAfterRestore,
	})
	fmt.Printf("  旧游标续查：errors.Is(err, ErrQueryChanged)=%v errors.Is(err, ErrInvalidArgument)=%v\n",
		errors.Is(err, indexroom.ErrQueryChanged), errors.Is(err, indexroom.ErrInvalidArgument))
	restart, err := target.QueryTxs(indexroom.TxQuery{From: 1, To: 4, TxIDs: querySet, PageSize: 2})
	if err != nil {
		panic(err)
	}
	fmt.Printf("  从空游标重新开始：ToHeight=%d 命中：", restart.ToHeight)
	for _, hit := range restart.Hits {
		fmt.Printf("%d/%s ", hit.Height, hit.TxID)
	}
	fmt.Printf("有后续游标=%v\n", restart.NextCursor != "")
}
