		errors.Is(err, io.ErrUnexpectedEOF),
		errors.Is(err, errStorage))
	fmt.Printf("  错误信息以 \"indexroom: read snapshot:\" 开头：%v\n",
		strings.HasPrefix(err.Error(), "indexroom: read snapshot:"))
}

